{
  "source_routes": [
    {
      "source_handle": "P0001",
      "paper_title": "Metalenses at visible wavelengths: past, present, perspectives",
      "chapter_ids": ["CH1", "CH2", "CH3"],
      "specific_usable_material": "该文为综述提供物理基准：明确单界面几何导致高 NA 下视场极小（<5 µm）的硬约束，并阐述衍射元件效率随波长变化的 sinc²规律。在设计机制上，对比波导型与共振型元原子的相位控制差异，指出斜入射下反对称模式耦合导致的效率下降。实证方面，提供评估高性能宣称的批判性视角，强调不应将单层金属透镜与多片商业物镜直接对比，需区分聚焦效率与像差校正能力。"
    },
    {
      "source_handle": "P0002",
      "paper_title": "Bandwidth bounds for wide-field-of-view dispersion-engineered achromatic metalenses",
      "chapter_ids": ["CH1", "CH2"],
      "specific_usable_material": "本文量化了宽视场色散工程金属透镜的带宽物理上限，揭示大 NA 与大视场对带宽的双重压缩效应及高视场下的饱和趋势。其理论模型基于局部相互作用假设，推导了无像差成像所需的群延迟空间分布特征，指出有限孔径下最大群延迟需求并非总出现在最大入射角。该材料用于确立理论界限，解释为何实际器件难以同时实现超宽带与大视场，并作为评估实验数据是否触及物理极限的参照。"
    }
  ]
}

